const fs = require('fs').promises;

async function runAirdrop() {
  const apiKey = process.env.CROSSMINT_API_KEY;
  if (!apiKey) {
    console.error("Error: CROSSMINT_API_KEY environment variable is not set.");
    process.exit(1);
  }

  const recipientsFile = '/home/user/recipients.json';
  const summaryFile = '/home/user/airdrop_summary.json';

  let recipients = [];
  try {
    const data = await fs.readFile(recipientsFile, 'utf8');
    recipients = JSON.parse(data);
    if (!Array.isArray(recipients)) {
      throw new Error("recipients.json must contain an array of email strings.");
    }
  } catch (err) {
    console.error(`Failed to read or parse ${recipientsFile}:`, err.message);
    process.exit(1);
  }

  const results = [];
  console.log(`Starting airdrop for ${recipients.length} recipients...`);

  for (const email of recipients) {
    const recipientStr = `email:${email}:polygon-amoy`;
    const payload = {
      recipient: recipientStr,
      metadata: {
        name: "Welcome NFT",
        description: "Airdrop token",
        image: "https://example.com/welcome.png"
      }
    };

    try {
      const response = await fetch('https://staging.crossmint.com/api/2022-06-09/collections/default/nfts', {
        method: 'POST',
        headers: {
          'x-api-key': apiKey,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(payload)
      });

      const responseText = await response.text();
      let responseData;
      try {
        responseData = JSON.parse(responseText);
      } catch (e) {
        responseData = responseText;
      }

      const isSuccess = response.status === 200 || response.status === 202;

      results.push({
        email,
        status: isSuccess ? "sent" : "error",
        response: responseData
      });

      console.log(`Processed ${email}: ${isSuccess ? 'Success' : 'Failed'}`);
    } catch (error) {
      console.error(`Network error processing ${email}:`, error.message);
      results.push({
        email,
        status: "error",
        response: { error: error.message }
      });
    }
  }

  const summary = {
    total: recipients.length,
    results
  };

  try {
    await fs.writeFile(summaryFile, JSON.stringify(summary, null, 2), 'utf8');
    console.log(`\nAirdrop complete. Summary written to ${summaryFile}`);
  } catch (err) {
    console.error(`Failed to write summary to ${summaryFile}:`, err.message);
  }
}

runAirdrop();

